1	use crate::hints::Hint;
2	use crate::kv::KvItem;
3	use crate::recovery::RecoveryHint;
4	use crate::toon::Value;
5	
6	/// The serialisation format for `AgentResponse::render`.
7	#[derive(Debug, Clone, Copy, PartialEq, Eq, Default)]
8	#[non_exhaustive]
9	pub enum OutputFormat {
10	    /// Plain-text TOON / kv format. Default.
11	    #[default]
12	    Text,
13	    /// Compact JSON object.
14	    Json,
15	}
16	
17	#[derive(Debug, Clone, PartialEq, Eq)]
18	enum RenderTarget {
19	    Unset,
20	    Toon,
21	    Kv,
22	}
23	
24	/// Default per-cell truncation limit used by [`AgentResponse::new`].
25	pub const DEFAULT_TRUNCATE_CELLS: usize = 200;
26	
27	/// Builder for an agent-facing response.
28	#[derive(Debug, Clone)]
29	#[non_exhaustive]
30	pub struct AgentResponse {
31	    /// The TOON list slot: type name, fields, rows, total count, cell cap and truncation hint, kept as the options
32	    /// the renderer validates and renders by reference, so a render never copies the rows. Its `hints` stay empty:
33	    /// the response's hints are appended after the body instead.
34	    toon: crate::toon::ToonOptions,
35	    target: RenderTarget,
36	    single_item: Vec<KvItem>,
37	    hints: Vec<Hint>,
38	    recovery: Vec<RecoveryHint>,
39	    is_error: bool,
40	    human_content: Option<String>,
41	}
42	
43	impl AgentResponse {
44	    /// Create a new, empty response for the given type name.
45	    pub fn new(type_name: impl Into<String>) -> Self {
46	        Self {
47	            toon: crate::toon::ToonOptions::new(type_name, Vec::new(), Vec::new()).max_cell_len(DEFAULT_TRUNCATE_CELLS),
48	            target: RenderTarget::Unset,
49	            single_item: Vec::new(),
50	            hints: Vec::new(),
51	            recovery: Vec::new(),
52	            is_error: false,
53	            human_content: None,
54	        }
55	    }
56	
57	    /// Populate the TOON list path.
58	    #[must_use]
59	    pub fn items(mut self, rows: Vec<Vec<Value>>, fields: &[&str]) -> Self {
60	        self.toon.rows = rows;
61	        self.toon.fields = fields.iter().map(|s| (*s).to_string()).collect();
62	        self.target = RenderTarget::Toon;
63	        self
64	    }
65	
66	    /// Set the total available count.
67	    #[must_use]
68	    pub fn total_count(mut self, n: usize) -> Self {
69	        self.toon.total_count = Some(n);
70	        self
71	    }
72	
73	    /// Report a list cut in one call: sets the total count to `outcome.total_before` and, only when something was
74	    /// cut, appends [`TruncationOutcome::hint`](crate::truncation::TruncationOutcome::hint)`(guidance)`, so the
75	    /// `totalCount` and the `help[]` line always describe the same cut.
76	    ///
77	    /// It does not set the rows: the response holds TOON [`Value`] rows, not the caller's `T`, so pass `outcome.kept`
78	    /// (converted to rows) to [`items`](Self::items) yourself. Later [`total_count`](Self::total_count) or
79	    /// [`hints`](Self::hints) calls still override what this sets.
80	    ///
81	    /// ```
82	    /// use michi_core::toon::Value;
83	    /// use michi_core::{truncate_by_count, AgentResponse, OutputFormat};
84	    ///
85	    /// let outcome = truncate_by_count(vec![1, 2, 3, 4], 2);
86	    /// let rows = outcome.kept.iter().map(|n| vec![Value::Int(*n)]).collect();
87	    /// let r = AgentResponse::new("issues").items(rows, &["n"]).truncation(&outcome, "pass --limit 4");
88	    /// assert_eq!(
89	    ///     r.render(OutputFormat::Text),
90	    ///     "issues[2]{n}:\n  1\n  2\ntotalCount: 4\nhelp[1]: showing 2 of 4; pass --limit 4"
91	    /// );
92	    /// ```
93	    #[must_use]
94	    pub fn truncation<T>(
95	        mut self,
96	        outcome: &crate::truncation::TruncationOutcome<T>,
97	        guidance: impl Into<String>,
98	    ) -> Self {
99	        self.toon.total_count = Some(outcome.total_before);
100	        if let Some(hint) = outcome.hint(guidance) {
101	            self.hints.push(hint);
102	        }
103	        self
104	    }
105	
106	    /// Populate the KV single-item path.
107	    #[must_use]
108	    pub fn kv_items(mut self, items: Vec<KvItem>) -> Self {
109	        self.single_item = items;
110	        self.target = RenderTarget::Kv;
111	        self
112	    }
113	
114	    /// Append a contextual hint.
115	    #[must_use]
116	    pub fn hint(mut self, hint: impl Into<String>) -> Self {
117	        self.hints.push(Hint::new(hint));
118	        self
119	    }
120	
121	    /// Replace all contextual hints.
122	    #[must_use]
123	    pub fn hints(mut self, hints: Vec<Hint>) -> Self {
124	        self.hints = hints;
125	        self
126	    }
127	
128	    /// Append a recovery hint.
129	    #[must_use]
130	    pub fn recovery_hint(mut self, r: RecoveryHint) -> Self {
131	        self.recovery.push(r);
132	        self
133	    }
134	
135	    /// Set the max string cell length, in chars, before truncation on the TOON path. Default:
136	    /// [`DEFAULT_TRUNCATE_CELLS`].
137	    ///
138	    /// The limit counts characters before TOON escaping and quoting, so a cell that needs quotes or escapes is
139	    /// written longer than `limit` (see [`crate::toon::ToonOptions::max_cell_len`]). The KV path is never truncated.
140	    #[must_use]
141	    pub fn truncate_cells_at(mut self, limit: usize) -> Self {
142	        self.toon.max_cell_len = limit;
143	        self
144	    }
145	
146	    /// Set the caller's instruction for getting a cut TOON cell in full. When a cell was cut, michi adds one line to
147	    /// `help[]` (after your own hints) that names the `truncated` block and this instruction (see
148	    /// [`crate::toon::ToonOptions::truncation_hint`]). Unset by default: michi never invents a parameter the tool
149	    /// may not have, and the `truncated` block still reports each cut. Pass tool-author text, never data.
150	    #[must_use]
151	    pub fn truncation_hint(mut self, hint: impl Into<String>) -> Self {
152	        self.toon.truncation_hint = Some(hint.into());
153	        self
154	    }
155	
156	    /// Mark this response as an error state.
157	    #[must_use]
158	    pub fn as_error(mut self) -> Self {
159	        self.is_error = true;
160	        self
161	    }
162	
163	    /// Attach a human-facing companion block (`audience: user`).
164	    #[must_use]
165	    pub fn human_content(mut self, text: impl Into<String>) -> Self {
166	        self.human_content = Some(text.into());
167	        self
168	    }
169	
170	    /// The TOON body, and whether it is a validation-failure error block instead of the requested rows.
171	    ///
172	    /// The third item is the `help[]` line michi adds when it cut a cell and a truncation hint is set.
173	    fn toon_body(&self) -> (String, bool, Option<Hint>) {
174	        match self.toon.validate() {
175	            Ok(doc) => {
176	                let (body, extra) = doc.render_parts();
177	                (body, false, extra.map(Hint::new))
178	            }
179	            Err(e) => (validation_error_body("toon_validation_failed", &e.to_string()), true, None),
180	        }
181	    }
182	
183	    /// The caller's hints, then michi's own truncation line when there is one: a single `help` block.
184	    fn hints_with<'a>(&'a self, extra: Option<&Hint>) -> std::borrow::Cow<'a, [Hint]> {
185	        match extra {
186	            None => std::borrow::Cow::Borrowed(&self.hints),
187	            Some(e) => {
188	                let mut all = Vec::with_capacity(self.hints.len() + 1);
189	                all.extend(self.hints.iter().cloned());
190	                all.push(e.clone());
191	                std::borrow::Cow::Owned(all)
192	            }
193	        }
194	    }
195	
196	    /// The KV body, and whether it is a validation-failure error block instead of the requested items (a duplicate
197	    /// or reserved key, see [`crate::kv::KvError`]).
198	    fn kv_body(&self) -> (String, bool) {
199	        // `render_kv` renders nothing for no items, dropping the count; a response that set one still reports it,
200	        // as the TOON path does (`t: []\ntotalCount: 0`).
201	        if self.single_item.is_empty() {
202	            let body = self.toon.total_count.map_or_else(String::new, |n| format!("totalCount: {n}"));
203	            return (body, false);
204	        }
205	        match crate::kv::render_kv(&self.single_item, self.toon.total_count, &[]) {
206	            Ok(body) => (body, false),
207	            Err(e) => (validation_error_body("kv_validation_failed", &e.to_string()), true),
208	        }
209	    }
210	
211	    /// The selected body, and whether this response is an error: set by `as_error()` or by a body that failed
212	    /// validation. Every output surface reads its error flag from here so text, JSON and MCP never disagree.
213	    fn body(&self) -> (String, bool, Option<Hint>) {
214	        let (body, failed, extra) = match self.target {
215	            RenderTarget::Toon | RenderTarget::Unset => self.toon_body(),
216	            RenderTarget::Kv => {
217	                let (body, failed) = self.kv_body();
218	                (body, failed, None)
219	            }
220	        };
221	        (body, failed || self.is_error, extra)
222	    }
223	
224	    /// Compose the text document: body, help block, recovery block. Each part is a TOON 4.4 document without a
225	    /// trailing newline and the append helpers join them with one LF, so the result is one root object whose keys
226	    /// are unique (the body cannot use `totalCount`, `help`, `recovery` or `truncated`). Appends to `body` in place.
227	    fn finish_text(&self, mut body: String, extra: Option<&Hint>) -> String {
228	        let hints = self.hints_with(extra);
229	        if !hints.is_empty() || !self.recovery.is_empty() {
230	            body.reserve(1 + hints.len() * 60 + self.recovery.len() * 80);
231	        }
232	        crate::hints::append_hints(&mut body, &hints);
233	        crate::recovery::append_recovery(&mut body, &self.recovery);
234	        body
235	    }
236	
237	    /// Render the response in the requested format.
238	    #[must_use]
239	    pub fn render(&self, format: OutputFormat) -> String {
240	        match format {
241	            OutputFormat::Text => self.render_text(),
242	            OutputFormat::Json => self.render_json(),
243	        }
244	    }
245	
246	    /// Render via the TOON path.
247	    #[must_use]
248	    pub fn render_toon(&self) -> String {
249	        let (body, _, extra) = self.toon_body();
250	        self.finish_text(body, extra.as_ref())
251	    }
252	
253	    /// Render via the KV path.
254	    #[must_use]
255	    pub fn render_kv(&self) -> String {
256	        self.finish_text(self.kv_body().0, None)
257	    }
258	
259	    fn render_text(&self) -> String {
260	        let (body, _, extra) = self.body();
261	        self.finish_text(body, extra.as_ref())
262	    }
263	
264	    /// Whether this response is an error: `as_error()` was called, or the TOON rows or KV items failed validation and
265	    /// the body is a `toon_validation_failed` or `kv_validation_failed` error block. Validates without rendering.
266	    #[must_use]
267	    pub fn is_error(&self) -> bool {
268	        self.is_error
269	            || match self.target {
270	                RenderTarget::Toon | RenderTarget::Unset => self.toon.validate().is_err(),
271	                RenderTarget::Kv => crate::kv::validate_keys(&self.single_item).is_err(),
272	            }
273	    }
274	
275	    /// Render just the `help[N]:` block for `self.hints`.
276	    #[must_use]
277	    pub fn render_hints_only(&self) -> String {
278	        crate::hints::render_hints(&self.hints)
279	    }
280	
281	    /// Render for the given audience.
282	    #[must_use]
283	    pub fn render_for(&self, audience: crate::audience::Audience) -> String {
284	        match audience {
285	            crate::audience::Audience::Assistant => self.render_text(),
286	            crate::audience::Audience::User => self.human_content.clone().unwrap_or_else(|| self.render_text()),
287	        }
288	    }
289	
290	    /// Whether `.human_content()` was set on this builder.
291	    #[must_use]
292	    pub fn has_human_content(&self) -> bool {
293	        self.human_content.is_some()
294	    }
295	
296	    /// Build the MCP `CallToolResult` for this response.
297	    #[must_use]
298	    pub fn to_call_tool_result(&self) -> crate::mcp::CallToolResult {
299	        let (body, is_error, extra) = self.body();
300	        let structured_content = self.json_from_body(&body, is_error, extra.as_ref());
301	        let mut content = vec![crate::mcp::ContentBlock {
302	            text: self.finish_text(body, extra.as_ref()),
303	            audience: vec![crate::audience::Audience::Assistant],
304	        }];
305	        if let Some(human) = &self.human_content {
306	            content.push(crate::mcp::ContentBlock {
307	                text: human.clone(),
308	                audience: vec![crate::audience::Audience::User],
309	            });
310	        }
311	        crate::mcp::CallToolResult { content, is_error, structured_content }
312	    }
313	
314	    fn render_json(&self) -> String {
315	        let (body, is_error, extra) = self.body();
316	        self.json_from_body(&body, is_error, extra.as_ref())
317	    }
318	
319	    fn json_from_body(&self, body: &str, is_error: bool, extra: Option<&Hint>) -> String {
320	        let hints = self.hints_with(extra);
321	        let capacity =
322	            body.len() + hints.iter().map(|h| h.as_str().len() + 16).sum::<usize>() + self.recovery.len() * 64 + 64;
323	        let mut out = String::with_capacity(capacity);
324	        out.push_str("{\"body\":");
325	        json_string(&mut out, body);
326	        out.push_str(",\"hints\":[");
327	        for (i, h) in hints.iter().enumerate() {
328	            if i > 0 {
329	                out.push(',');
330	            }
331	            json_string(&mut out, h.as_str());
332	        }
333	        out.push_str("],\"recovery\":[");
334	        for (i, r) in self.recovery.iter().enumerate() {
335	            if i > 0 {
336	                out.push(',');
337	            }
338	            out.push_str("{\"tool\":");
339	            json_string(&mut out, &r.tool);
340	            out.push_str(",\"params\":");
341	            crate::recovery::push_params_json(&mut out, &r.params);
342	            if let Some(reason) = &r.reason {
343	                out.push_str(",\"reason\":");
344	                json_string(&mut out, reason);
345	            }
346	            out.push('}');
347	        }
348	        out.push_str("],\"isError\":");
349	        out.push_str(if is_error { "true" } else { "false" });
350	        out.push('}');
351	        out
352	    }
353	}
354	
355	/// The body that replaces rows or items that cannot form a valid document: `error: <code>` and the quoted message.
356	fn validation_error_body(code: &str, message: &str) -> String {
357	    let message = crate::toon::escape_value(message);
358	    let mut out = String::with_capacity(17 + code.len() + message.len());
359	    out.push_str("error: ");
360	    out.push_str(code);
361	    out.push_str("\nmessage: ");
362	    out.push_str(&message);
