        let cases = [
            AgentResponse::new("t"),
            AgentResponse::new("help"),
            AgentResponse::new("t").items(vec![vec![Value::Int(1)]], &["a"]),
            AgentResponse::new("t").items(vec![vec![Value::Int(1)]], &["a", "b"]),
            AgentResponse::new("t").kv_items(vec![]),
