#[non_exhaustive]
pub enum SectionBody {
    /// A uniform list, rendered as a TOON list with the response's per-cell truncation applied.
    Toon {
        /// Ordered, distinct field names.
        fields: Vec<String>,
        /// Rows, parallel to `fields`.
        rows: Vec<Vec<Value>>,
